import{_ as t,c as i,o as l,j as n,Y as s,t as o}from"./chunks/framework.BNTND4LZ.js";const f=JSON.parse('{"title":"queue | x-cmd man (man7) | implementations of linked lists and queues","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | queue - implementations of linked lists and queues","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"queue | x-cmd man (man7) | implementations of linked lists and queues"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | queue - implementations of linked lists and queues"}]]},"headers":[],"params":{"isMan":true,"man":"queue","category":"man7","desc":"implementations of linked lists and queues"},"relativePath":"man7/queue.md","filePath":"man7/[man].md"}'),r={name:"man7/queue.md"},d={class:"visually-hidden"};function u(a,e,h,p,c,m){return l(),i("div",null,[n("h1",d,o(a.$params.man),1),e[0]||(e[0]=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>queue - implementations of linked lists and queues</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The <em>&lt;sys/queue.h&gt;</em> header file provides a set of macros that define and operate on the following data structures:</p><dl><dt>SLIST</dt><dd>singly linked lists</dd><dt>LIST</dt><dd>doubly linked lists</dd><dt>STAILQ</dt><dd>singly linked tail queues</dd><dt>TAILQ</dt><dd>doubly linked tail queues</dd><dt>CIRCLEQ</dt><dd>doubly linked circular queues</dd></dl><p>All structures support the following functionality:</p><ul><li><p>Insertion of a new entry at the head of the list.</p></li><li><p>Insertion of a new entry after any element in the list.</p></li><li><p>O(1) removal of an entry from the head of the list.</p></li><li><p>Forward traversal through the list.</p></li></ul><p>Code size and execution time depend on the complexity of the data structure being used, so programmers should take care to choose the appropriate one.</p><h3 id="singly-linked-lists-slist" tabindex="-1">Singly linked lists (SLIST) <a class="header-anchor" href="#singly-linked-lists-slist" aria-label="Permalink to &quot;Singly linked lists (SLIST)&quot;">​</a></h3><p>Singly linked lists are the simplest and support only the above functionality. Singly linked lists are ideal for applications with large datasets and few or no removals, or for implementing a LIFO queue. Singly linked lists add the following functionality:</p><ul><li>O(n) removal of any entry in the list.</li></ul><h3 id="singly-linked-tail-queues-stailq" tabindex="-1">Singly linked tail queues (STAILQ) <a class="header-anchor" href="#singly-linked-tail-queues-stailq" aria-label="Permalink to &quot;Singly linked tail queues (STAILQ)&quot;">​</a></h3><p>Singly linked tail queues add the following functionality:</p><ul><li><p>Entries can be added at the end of a list.</p></li><li><p>O(n) removal of any entry in the list.</p></li><li><p>They may be concatenated.</p></li></ul><p>However:</p><ul><li><p>All list insertions must specify the head of the list.</p></li><li><p>Each head entry requires two pointers rather than one.</p></li></ul><p>Singly linked tail queues are ideal for applications with large datasets and few or no removals, or for implementing a FIFO queue.</p><h3 id="doubly-linked-data-structures" tabindex="-1">Doubly linked data structures <a class="header-anchor" href="#doubly-linked-data-structures" aria-label="Permalink to &quot;Doubly linked data structures&quot;">​</a></h3><p>All doubly linked types of data structures (lists and tail queues) additionally allow:</p><ul><li><p>Insertion of a new entry before any element in the list.</p></li><li><p>O(1) removal of any entry in the list.</p></li></ul><p>However:</p><ul><li>Each element requires two pointers rather than one.</li></ul><h3 id="doubly-linked-lists-list" tabindex="-1">Doubly linked lists (LIST) <a class="header-anchor" href="#doubly-linked-lists-list" aria-label="Permalink to &quot;Doubly linked lists (LIST)&quot;">​</a></h3><p>Linked lists are the simplest of the doubly linked data structures. They add the following functionality over the above:</p><ul><li>They may be traversed backwards.</li></ul><p>However:</p><ul><li>To traverse backwards, an entry to begin the traversal and the list in which it is contained must be specified.</li></ul><h3 id="doubly-linked-tail-queues-tailq" tabindex="-1">Doubly linked tail queues (TAILQ) <a class="header-anchor" href="#doubly-linked-tail-queues-tailq" aria-label="Permalink to &quot;Doubly linked tail queues (TAILQ)&quot;">​</a></h3><p>Tail queues add the following functionality:</p><ul><li><p>Entries can be added at the end of a list.</p></li><li><p>They may be traversed backwards, from tail to head.</p></li><li><p>They may be concatenated.</p></li></ul><p>However:</p><ul><li><p>All list insertions and removals must specify the head of the list.</p></li><li><p>Each head entry requires two pointers rather than one.</p></li></ul><h3 id="doubly-linked-circular-queues-circleq" tabindex="-1">Doubly linked circular queues (CIRCLEQ) <a class="header-anchor" href="#doubly-linked-circular-queues-circleq" aria-label="Permalink to &quot;Doubly linked circular queues (CIRCLEQ)&quot;">​</a></h3><p>Circular queues add the following functionality over the above:</p><ul><li>The first and last entries are connected.</li></ul><p>However:</p><ul><li>The termination condition for traversal is more complex.</li></ul><h2 id="standards" tabindex="-1">STANDARDS <a class="header-anchor" href="#standards" aria-label="Permalink to &quot;STANDARDS&quot;">​</a></h2><p>BSD.</p><h2 id="history" tabindex="-1">HISTORY <a class="header-anchor" href="#history" aria-label="Permalink to &quot;HISTORY&quot;">​</a></h2><p><em>&lt;sys/queue.h&gt;</em> macros first appeared in 4.4BSD.</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>Some BSDs provide SIMPLEQ instead of STAILQ. They are identical, but for historical reasons they were named differently on different BSDs. STAILQ originated on FreeBSD, and SIMPLEQ originated on NetBSD. For compatibility reasons, some systems provide both sets of macros. glibc provides both STAILQ and SIMPLEQ, which are identical except for a missing SIMPLEQ equivalent to <strong>STAILQ_CONCAT</strong>().</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>circleq</strong>(3), <strong>insque</strong>(3), <strong>list</strong>(3), <strong>slist</strong>(3), <strong>stailq</strong>(3), <strong>tailq</strong>(3)</p>',45))])}const q=t(r,[["render",u]]);export{f as __pageData,q as default};
